import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function TasksPage() {
  const navigate = useNavigate();
  const [tasks, setTasks] = useState([]);
  const [tasksCopied, setTasksCopied] = useState(false);
  const currentDay = parseInt(localStorage.getItem("currentDay") || "1");
  const roadmapPlan = JSON.parse(localStorage.getItem("roadmapPlan") || "[]");

  useEffect(() => {
    if (!tasksCopied && roadmapPlan.length > 0) {
      const carry = JSON.parse(localStorage.getItem("carryForward") || "[]");
      const allDailyTasks = roadmapPlan.flat();
      const tasksPerDay = 4;
      const startIdx = (currentDay - 1) * tasksPerDay;
      const todayTasks = allDailyTasks.slice(startIdx, startIdx + tasksPerDay);
      
      const taskList = [];
      // Add carry forward
      carry.forEach((task, i) => {
        taskList.push({ id: `carry-${i}`, label: task, done: false, isCarriedOver: true });
      });
      // Add new tasks
      todayTasks.forEach((task, idx) => {
        taskList.push({ id: `today-${idx}`, label: task, done: false, isCarriedOver: false });
      });
      
      setTasks(taskList);
      setTasksCopied(true);
    }
  }, [currentDay, tasksCopied, roadmapPlan]);

  const toggleTask = (id) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, done: !t.done } : t));
  };

  const handleSaveProgress = () => {
    const newlyCompleted = tasks.filter(t => t.done).map(t => t.label);
    const remaining = tasks.filter(t => !t.done).map(t => t.label);

    // 🛠️ Update Global Task Completion List
    const totalCompletedTasks = JSON.parse(localStorage.getItem("completedTasks") || "[]");
    const updatedTotalCompleted = Array.from(new Set([...totalCompletedTasks, ...newlyCompleted]));
    localStorage.setItem("completedTasks", JSON.stringify(updatedTotalCompleted));

    // Save carry forward for tomorrow
    localStorage.setItem("carryForward", JSON.stringify(remaining));
    localStorage.setItem("currentDay", currentDay + 1);

    // Track completed days for the progress bar
    const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
    if (remaining.length === 0 && !completedDays.includes(currentDay)) {
      completedDays.push(currentDay);
    }
    localStorage.setItem("completedDays", JSON.stringify(completedDays));

    alert(remaining.length > 0 ? "Progress saved. Incomplete tasks carried to tomorrow." : "Day complete! 🎉");
    setTasksCopied(false);
    navigate('/tasks');
  };

  return (
    <div className="space-y-8">
      <div className="rounded-[2rem] border border-slate-300 bg-white p-8 shadow-lg">
        <h2 className="text-3xl font-semibold">📅 Day {currentDay} Tasks</h2>
        <div className="mt-4 flex items-center gap-4">
          <div className="flex-1 bg-slate-200 rounded-full h-2">
            <div className="bg-teal-500 h-2 rounded-full transition-all" 
                 style={{ width: `${tasks.length > 0 ? (tasks.filter(t => t.done).length / tasks.length) * 100 : 0}%` }}></div>
          </div>
          <span className="text-sm font-medium">{tasks.filter(t => t.done).length}/{tasks.length} done</span>
        </div>
      </div>

      <div className="rounded-[2rem] border border-slate-300 bg-white p-8 shadow-lg space-y-4">
        {tasks.map((task) => (
          <button key={task.id} onClick={() => toggleTask(task.id)}
            className={`w-full flex items-center gap-4 rounded-3xl border-2 px-5 py-4 text-left transition ${
              task.done ? 'border-teal-400 bg-teal-50' : 'border-slate-200 bg-white'
            }`}>
            <div className={`h-6 w-6 rounded-lg border-2 flex items-center justify-center ${task.done ? 'bg-teal-500 border-teal-500' : 'border-slate-300'}`}>
              {task.done && <span className="text-white text-xs">✓</span>}
            </div>
            <span className={`flex-1 ${task.done ? 'line-through text-slate-400' : 'text-slate-700'}`}>{task.label}</span>
          </button>
        ))}
        <Button onClick={handleSaveProgress} className="w-full mt-6">Save Progress & Continue →</Button>
      </div>
    </div>
  );
}
